inputs.script:
// Get the input configuration
let config = input.config();
let id = Number(config.id); // Convert to number to match the field type

// Get the table
let table = base.getTable('Workspace IDs');

// Query all records from the table
let query = await table.selectRecordsAsync();

// Find the record where the "ID" field matches our input
let matchingRecord = query.records.find(record => {
    return record.getCellValue('ID') === id;
});

// Output the result
if (matchingRecord) {
    let emailBisonAPI = matchingRecord.getCellValue('EmailBison API');
    output.set('emailBisonAPI', emailBisonAPI);
    console.log(`EmailBison API: ${emailBisonAPI}`);
} else {
    console.log(`No record found with ID: ${id}`);
    output.set('emailBisonAPI', null);
}

// Alternative-contact new-email sender v3. Future sends only; fail closed.
const cfg = input.config();
const RECORD_ID = String(cfg.recordId || '');
const SENDER_EMAIL_ID = String(cfg.senderEmailId || '');
const API_TOKEN = String(cfg.api_key || '');
const SEND_GATE = cfg.sendGate === true;
const API_ROOT = 'https://send.dulcy.io/api';
const table = base.getTable('Emails');

function address(value) {
  if (value && typeof value === 'object') return address(value.address || value.email_address || value.email || '');
  const text = String(value || '').trim().toLowerCase();
  const angle = text.match(/<([^<>]+)>/);
  return (angle ? angle[1] : text).trim();
}

function validEmail(value) {
  return /^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(value);
}

async function requestJson(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: {
      Authorization: `Bearer ${API_TOKEN}`,
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  const raw = await response.text();
  let payload = {};
  if (raw) {
    try { payload = JSON.parse(raw); }
    catch { throw new Error(`EmailBison returned non-JSON HTTP ${response.status}`); }
  }
  if (!response.ok || payload?.error || payload?.success === false) {
    throw new Error(`EmailBison request failed with HTTP ${response.status}`);
  }
  return payload;
}

function rowsFrom(payload) {
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.data?.data)) return payload.data.data;
  if (Array.isArray(payload?.records)) return payload.records;
  return [];
}

async function authoritativeAccounts() {
  const accounts = [];
  for (let page = 1; page <= 100; page += 1) {
    const payload = await requestJson(`${API_ROOT}/sender-emails?per_page=100&page=${page}`);
    accounts.push(...rowsFrom(payload));
    const meta = payload?.meta || payload?.data?.meta || {};
    const current = Number(meta.current_page || page);
    const last = Number(meta.last_page || current);
    const next = payload?.next_page_url || payload?.links?.next || meta.next_page_url;
    if (!next && current >= last) return accounts;
    if (!next && !Number.isFinite(last)) throw new Error('Sender account pagination is ambiguous');
  }
  throw new Error('Sender account pagination exceeded the safety limit');
}

function explicitTime(raw) {
  if (typeof raw !== 'string' || !/(?:Z|[+-]\d{2}:?\d{2}|\b(?:UT|UTC|GMT))\s*(?:\([^)]*\))?$/i.test(raw.trim())) return null;
  const millis = Date.parse(raw);
  return Number.isFinite(millis) ? new Date(millis).toISOString() : null;
}

function confirmedSend(payload) {
  const reply = payload?.data?.reply || payload?.data || {};
  const id = String(reply.id || reply.uuid || '');
  const status = String(reply.folder || reply.status || '').toLowerCase();
  const sentAt = explicitTime(reply.sent_at)
    || explicitTime(reply.date_sent)
    || (String(reply.type || '').toLowerCase() === 'outgoing email' ? explicitTime(reply.date_received) : null);
  if (!id || !['sent', 'delivered'].includes(status) || !sentAt || Date.parse(sentAt) > Date.now() + 60000) {
    throw new Error('Submission is unconfirmed or queued. Do not mark sent or retry automatically; reconcile by provider message ID.');
  }
  return { id, sentAt };
}

if (!SEND_GATE) throw new Error('Send gate is not checked');
if (!RECORD_ID || !SENDER_EMAIL_ID || !API_TOKEN) throw new Error('Missing record, sender, or API identity');
const record = await table.selectRecordAsync(RECORD_ID);
if (!record) throw new Error('Record not found');

const recipient = address(cfg.alt_email);
const recipientName = String(cfg.alt_name || '').trim();
const subject = String(cfg.subject || '').trim();
const body = String(cfg.body || '');
if (!validEmail(recipient) || !subject || !body.trim()) throw new Error('Missing or invalid alternative contact, subject, or body');

const senderPayload = await requestJson(`${API_ROOT}/sender-emails/${encodeURIComponent(SENDER_EMAIL_ID)}`);
const sender = senderPayload?.data;
const senderAddress = address(sender);
if (!sender || String(sender.id) !== SENDER_EMAIL_ID || !validEmail(senderAddress)) {
  throw new Error('Authoritative sender account unavailable or mismatched');
}
const accounts = await authoritativeAccounts();
const internalAddresses = new Set(accounts.map(address).filter(validEmail));
internalAddresses.add(senderAddress);
if (internalAddresses.has(recipient)) throw new Error('Alternative recipient is the sender or a known sender alias');

const result = await requestJson(`${API_ROOT}/replies/new`, {
  method: 'POST',
  body: JSON.stringify({
    subject,
    message: body,
    sender_email_id: Number(SENDER_EMAIL_ID),
    use_dedicated_ips: true,
    content_type: 'html',
    to_emails: [{ name: recipientName, email_address: recipient }],
  }),
});
const confirmation = confirmedSend(result);

await table.updateRecordAsync(RECORD_ID, {
  'OOO - Subsequence Email Sent': true,
});
output.set('providerMessageId', confirmation.id);
output.set('sentAt', confirmation.sentAt);
